package com.northstarbank.console.security;
import com.northstarbank.console.integration.TierClient;import org.springframework.http.HttpStatus;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;
@Service public class AuthorizationService{private final TierClient tiers;public AuthorizationService(TierClient t){tiers=t;}public SessionUser user(){return(SessionUser)SecurityContextHolder.getContext().getAuthentication().getPrincipal();}public TierClient.Decision require(String action,String branch,boolean vulnerable){return require(action,branch,vulnerable,null);}public TierClient.Decision require(String action,String branch,boolean vulnerable,String requester){var d=tiers.decide(user().token(),action,branch,vulnerable,requester);if(!d.allowed())throw new ResponseStatusException(HttpStatus.NOT_FOUND);return d;}}
